import{entityInstance}from"../entity/friendly-link.js";export function list(t){const n=t.page||1,e=t.size||15;return entityInstance.findAndCountAll({offset:(n-1)*e,limit:e}).then(t=>({list:t.rows.map(t=>t.get({plain:!0})),total:t.count,page:n,size:e}))}export function allList(){return entityInstance.findAll().then(t=>t.map(t=>t.get({plain:!0})))}export async function findById(t){const n=await entityInstance.findByPk(t);return n&&n.get({plain:!0})||void 0}export async function find(t){return(await allList()).find(t)}export async function filter(t){return(await allList()).filter(t)}export async function add(t){return entityInstance.create(t)}export async function update(t,n){return t.update(n)}export async function delete_(t){if(Array.isArray(t)){for(const n of t)await n.destroy();return t.length}return await t.destroy(),1}